module rescue_rangers(\n    input clk,\n    input rst_n,\n    input start,\n    input signed [15:0] x1,\n    input signed [15:0] y1,\n    input signed [15:0] x2,\n    input signed [15:0] y2,\n    input [15:0] v_max,\n    input [15:0] t,\n    input signed [15:0] vx,\n    input signed [15:0] vy,\n    input signed [15:0] wx,\n    input signed [15:0] wy,\n    output reg [31:0] time_result,\n    output reg done\n);\n\n    localparam [1:0] IDLE = 2'b00;\n    localparam [1:0] COMPUTE = 2'b01;\n    localparam [1:0] ITERATE = 2'b10;\n    localparam [1:0] FINISH = 2'b11;\n    \n    reg [1:0] state, next_state;\n    reg [5:0] iteration;\n    reg [31:0] low, high;\n    reg [31:0] mid;\n    reg condition_met;\n    \n// Combinational wind displacement calculation (using mid)\n    always @(*) begin\n        reg [31:0] t_scaled = t << 16;  // Convert to Q16.16\n        reg [31:0] t1, t2;\n        \n        // Calculate active wind periods\n        if (mid < t_scaled) begin\n            t1 = mid;\n            t2 = 32'd0;\n        end else begin\n            t1 = t_scaled;\n            t2 = mid - t_scaled;\n        end\n        \n        // Calculate wind displacement (Q16.16)\n        reg signed [31:0] wind_x_displacement = (((vx * t1) >>> 16) + ((wx * t2) >>> 16));\n        reg signed [31:0] wind_y_displacement = (((vy * t1) >>> 16) + ((wy * t2) >>> 16));\n        \n        // Calculate remaining displacement\n        reg signed [31:0] dx = ((x2 - x1) << 16) - wind_x_displacement;\n        reg signed [31:0] dy = ((y2 - y1) << 16) - wind_y_displacement;\n        \n        // Calculate left and right squared terms\n        reg signed [63:0] left_term = dx * dx + dy * dy;  // Q32.32\n        reg signed [63:0] v_max_sq = (v_max * v_max);\n        reg signed [63:0] right_term = (((v_max_sq * mid) >>> 16) * ((mid) >>> 0));\n        \n        condition_met = (left_term <= right_term);\n    end\n    \n// State machine and binary search control\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            time_result <= 32'd0;\n            iteration <= 6'd0;\n            low <= 32'd0;\n            high <= (1000000000 << 16);  // Q16.16 representation of 1e9\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        low <= 32'd0;\n                        high <= (1000000000 << 16);\n                        iteration <= 6'd0;\n                        state <= COMPUTE;\n                    end\n                end\n                \n                COMPUTE: begin\n                    mid <= (low + high) >> 1;  // Calculate midpoint\n                    state <= ITERATE;\n                end\n                \n                ITERATE: begin\n                    if (condition_met) high <= mid;\n                    else low <= mid;\n                    \n                    if (iteration == 6'd50) begin\n                        time_result <= mid;\n                        state <= FINISH;\n                    end else begin\n                        iteration <= iteration + 6'd1;\n                        state <= COMPUTE;\n                    end\n                end\n                \n                FINISH: begin\n                    done <= 1'b1;\n                    if (!start) state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule